def fn(x):
    import string
    # QWERTY substitution alphabet
    plain = string.ascii_lowercase
    cipher = "qwertyuiopasdfghjklzxcvbnm"
    # build translation dictionaries for lower and upper case
    trans = {p: c for p, c in zip(plain, cipher)}
    trans.update({p.upper(): c.upper() for p, c in zip(plain, cipher)})
    # translate
    return ''.join(trans.get(ch, ch) for ch in x)

